import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3 } = ctx.THREE;

  // Root container
  const rootGroup = new Group();

  // Color Palette
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  // --- STAGE BACKDROP (Engineered Gradient to avoid flat void) ---
  const backdropGeo = new PlaneGeometry(8, 7);
  const backdropMat = new MeshBasicNodeMaterial({ depthWrite: false });

  // Create solid vertical gradient using TSL
  const topColor = color(colors.surface);
  const bottomColor = color(colors.ink);
  backdropMat.colorNode = mix(bottomColor, topColor, uv().y);

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  rootGroup.add(backdrop);

  // --- HERO SPRITE CARD ---
  // Aspect ratio 512 / 320 = 1.6. Sized to balance nicely on screen.
  const spriteWidth = 3.6;
  const spriteHeight = 3.6 / 1.6;
  const spriteGeo = new PlaneGeometry(spriteWidth, spriteHeight);

  const spriteMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: true,
    opacity: 0.0 // Start at 0 for fade-up entry
  });

  const spriteMesh = new Mesh(spriteGeo, spriteMat);
  spriteMesh.position.set(0, 0, 0.2);
  rootGroup.add(spriteMesh);

  // Load the texture and apply it
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      spriteMat.colorNode = texture;
      spriteMat.needsUpdate = true;
    }).catch((err) => {
      console.warn('Failed to load sprite texture:', err);
    });
  }

  // --- SUBTLE AMBIENT ANIMATION (Static entry but soft breathe) ---
  const exitTimeline = gsap.timeline();

  // Fade and slide up entry
  gsap.fromTo(spriteMesh.position, 
    { y: -0.3 }, 
    { y: 0, duration: 1.2, ease: 'power3.out' }
  );
  gsap.fromTo(spriteMat, 
    { opacity: 0 }, 
    { opacity: 1, duration: 0.8, ease: 'power2.out' }
  );

  // Idle micro-movement: subtle floating
  const idleTween = gsap.to(spriteMesh.position, {
    y: '+=0.04',
    duration: 3,
    repeat: -1,
    yoyo: true,
    ease: 'power1.inOut'
  });

  // --- BILLBOARD BEHAVIOR ---
  // Billboard facing logic running on anim framework if needed, or simple static alignment.
  // Standard orthographic/perspective camera alignment for a flat UI element.

  // Cleanup interface
  rootGroup.userData = {
    cleanup() {
      idleTween.kill();
      exitTimeline.kill();
      backdropGeo.dispose();
      backdropMat.dispose();
      spriteGeo.dispose();
      spriteMat.dispose();
    }
  };

  return rootGroup;
}
